pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address receiver, address actor) public {
        vm.assume(receiver != address(0));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e18);

        // fund the contract so the transfer can succeed
        vm.deal(address(c), 10e18);
        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

