pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address receiver) public {
        // Admissible domain: receiver nonzero, amount positive and small enough
        // to avoid overflow in the mutant's `amount - 1` (always fine) and to
        // be fundable.
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint256).max - 1);

        // Fund the contract with EXACTLY `amount` wei, so a correct transfer
        // of `amount` drains it completely.
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        // setUp() deployed c, so owner == address(this); drive sendTo as owner.
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        // Rule: an admissible sendTo moves exactly `amount` wei out of c.
        // Reference: balance becomes 0. Mutant sends amount-1, leaving 1 wei.
        assertTrue(address(c).balance == 0, "sendTo must transfer exactly amount");
    }
}

