pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        amount = bound(amount, 1, 1 ether);
        vm.assume(actor != c.owner());
        vm.deal(address(c), amount);
        bool ok = true;
        vm.prank(actor);
        try c.sendTo(actor, amount) { ok = true; } catch { ok = false; }
        // Rule: any call by a non-owner must revert, so no non-owner call ever succeeds.
        assertTrue(!ok, "non-owner call must revert");
    }
}

