pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Receiver r;

    function setUp() public { c = new C(); r = new Receiver(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // owner is the deployer (this test contract); keep actor wide over all other callers
        vm.assume(actor != address(this));
        vm.assume(amount > 0);

        // fund c so the transfer to the receiver would succeed, isolating the check order
        vm.deal(address(c), amount);

        bool stringRevert = false;
        vm.prank(actor);
        try c.sendTo(address(r), amount) {
            stringRevert = false;
        } catch Error(string memory) {
            // revert data came from the receiver contract => the transfer already executed
            stringRevert = true;
        } catch {
            // bare require revert (e.g. the ownership check) => transfer never executed
            stringRevert = false;
        }

        // Reference: ownership check gates execution, so a failing call for a non-owner
        // is always a bare require revert, never the receiver's revert string.
        assertTrue(!stringRevert);
    }
}

contract Receiver {
    event Got();
    receive() external payable {
        emit Got();
        revert("receiver refused");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address receiver, uint amount) public {
        require(receiver != address(0));
        require(amount > 0);
        uint balBefore = address(c).balance;
        bool ok = true;
        // this test contract is not the owner of c, so P reverts; M would transfer
        (bool s1, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, receiver, amount));
        ok = s1;
        uint balAfter = address(c).balance;
        assert(!ok && balAfter == balBefore);
    }
}

